```dart
import 'package:multi_trigger_autocomplete/multi_trigger_autocomplete.dart';

Portal(
  child: MaterialApp(
    home: Scaffold(
      body: MultiTriggerAutocomplete(
        autocompleteTriggers: [
          AutocompleteTrigger(
            trigger: '@',
            optionsViewBuilder: (ctx, query, ctrl) => MentionAutocompleteOptions(
              query: query.query,
              onMentionUserTap: (user) => MultiTriggerAutocomplete.of(ctx).acceptAutocompleteOption(user.id),
            ),
          ),
        ],
        fieldViewBuilder: (ctx, ctrl, focus) => TextField(controller: ctrl, focusNode: focus),
      ),
    ),
  ),
);
```
